function pkceB64url(buf){var s='';var b=new Uint8Array(buf);for(var i=0;i<b.length;i++)s+=String.fromCharCode(b[i]);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}function pkceVerifier(){var a=new Uint8Array(32);crypto.getRandomValues(a);return pkceB64url(a)}function pkceAuthUrl(provider){var r=location.href.split('#')[0].split('?')[0]+location.search;try{var v=pkceVerifier();try{localStorage.setItem('gad_pkce_v',v)}catch(e){}return crypto.subtle.digest('SHA-256',new TextEncoder().encode(v)).then(function(d){return SUPABASE_URL+'/auth/v1/authorize?provider='+provider+'&redirect_to='+encodeURIComponent(r)+'&code_challenge='+pkceB64url(d)+'&code_challenge_method=S256'}).catch(function(){return SUPABASE_URL+'/auth/v1/authorize?provider='+provider+'&redirect_to='+encodeURIComponent(r)})}catch(e){return Promise.resolve(SUPABASE_URL+'/auth/v1/authorize?provider='+provider+'&redirect_to='+encodeURIComponent(r))}}function loginGoogle(){pkceAuthUrl('google').then(function(u){location.href=u})}
