function n2(x){x=Math.round(Number(x||0)*100)/100;return x%1===0?String(x):x.toFixed(2)}
function tm(s){try{return new Date(s).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'})}catch(e){return s}}
function waPhone(p){p=String(p||'').replace(/[^0-9]/g,'');if(p.indexOf('0020')===0)p=p.slice(2);if(p.indexOf('20')===0)return p;if(/^01[0125]/.test(p))return '2'+p;return p}
