function openChats(){$('chatview').style.display='none';chatOpenNo=null;api('/rest/v1/order_messages?select=*&order=created_at.desc&limit=300').then(function(r){return r.ok?r.json():[]}).then(function(rows){var by={};rows.forEach(function(m){if(!by[m.order_no])by[m.order_no]={msgs:[],unread:0};by[m.order_no].msgs.push(m);if(m.sender==='customer'&&!m.read_by_staff)by[m.order_no].unread++});var keys=Object.keys(by).sort(function(a,b){return new Date(by[b].msgs[0].created_at)-new Date(by[a].msgs[0].created_at)});chatGroups=keys.map(function(no){var g=by[no];var o=orders.filter(function(x){return x.order_no===no})[0];return {no:no,name:o?o.name:'',phone:o?o.phone:'',last:g.msgs[0],unread:g.unread,closed:o?!!o.chat_closed:false,order:o||null}});renderChatList()}).catch(function(){})}
