function autoAdvance(){var now=nowMs();if(now-lastAutoAdv<60000)return;var need=orders.some(function(o){var t=new Date(o.status_changed_at||o.created_at).getTime();return (o.status==='new'&&now-t>5*60000)||(o.status==='preparing'&&now-t>25*60000)});if(!need)return;lastAutoAdv=now;api('/rest/v1/rpc/auto_advance_orders',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(function(r){if(r.ok)poll()}).catch(function(){})}
