function checkSchedAlert(){var now=nowMs();var due=orders.filter(function(o){return o.status==='new'&&o.scheduled_at&&!schedAlerted[o.id]&&new Date(o.scheduled_at).getTime()>now&&new Date(o.scheduled_at).getTime()<=now+60*60000});if(!due.length)return;due.forEach(function(o){schedAlerted[o.id]=1});var o=due[0];beep();var b=$('ban');b.style.display='block';b.textContent='⏰ أوردر مجدول الساعة '+new Date(o.scheduled_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})+' — '+(due.length>1?('في '+due.length+' أوردرات مجدولة هتجهز قريب'):(o.order_no+' — '+(o.name||'')))+' — جهّز المطبخ';document.title='⏰ أوردر مجدول';try{if('Notification' in window&&Notification.permission==='granted')new Notification('أوردر مجدول قرب معاده',{body:'الساعة '+new Date(o.scheduled_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})+' — '+o.order_no})}catch(e){}}
