function oeBuildFlat(){var ov=(OE.prices&&OE.prices.overrides)||{},off=(OE.prices&&OE.prices.off)||[];var out=[];MENU.forEach(function(g){g.s.forEach(function(s){s.i.forEach(function(it){it.o.forEach(function(o){var k=s.k+'|'+it.n+'|'+(o.l||''),kl=it.n+'|'+(o.l||'');if(off.indexOf(k)>-1||off.indexOf(kl)>-1)return;out.push({n:it.n,l:o.l||'',p:(ov[k]!=null?ov[k]:(ov[kl]!=null?ov[kl]:o.p)),sec:s.t,sk:s.k})})})})});return out}
function oeCalc(){var sub=0;OE.lines.forEach(function(l){sub+=l.q*l.p});var fee=OE.order.fulfillment==='delivery'?((OE.order.delivery!=null)?Number(OE.order.delivery):((OE.cfg&&OE.cfg.fee!=null)?Number(OE.cfg.fee):30)):0;var disc=0,promoDropped=false;if(OE.promo&&OE.promo.type){if(OE.promo.eligible&&sub>=(OE.promo.min_order||0)){if(OE.promo.type==='percent')disc=Math.round(sub*OE.promo.value)/100;else if(OE.promo.type==='amount')disc=Math.min(sub,OE.promo.value);else if(OE.promo.type==='free_delivery')fee=0}else{promoDropped=true}}var rate=(OE.loy&&OE.loy.redeem_points_per_egp)?Number(OE.loy.redeem_points_per_egp):10;var ptsDisc=OE.order.points_redeemed>0?Math.floor(OE.order.points_redeemed/rate):0;var vatRate=((OE.cfg&&OE.cfg.vat!=null)?Number(OE.cfg.vat):14)/100;var base=Math.max(0,sub-disc-ptsDisc+fee);var vat=Math.round(base*vatRate*100)/100;var total=Math.round((base+vat)*100)/100;return{sub:sub,disc:disc,fee:fee,ptsDisc:ptsDisc,vat:vat,total:total,promoDropped:promoDropped}}
function oeRenderLines(){var L=document.getElementById('oeLines');var persons=[];OE.lines.forEach(function(l){var f=l['for']||OE.order.name;if(persons.indexOf(f)<0)persons.push(f)});OE.persons=persons;var pr=document.getElementById('oePersonRow');if(persons.length>1){pr.style.display='';var sel=document.getElementById('oePerson');var cur=sel.value;sel.innerHTML=persons.map(function(p){return '<option value="'+esc(p)+'">'+esc(p)+'</option>'}).join('');if(persons.indexOf(cur)>-1)sel.value=cur}else{pr.style.display='none'}var h='';persons.forEach(function(p){h+='<div style="font-weight:800;margin:10px 0 4px">👤 '+esc(p)+'</div>';OE.lines.forEach(function(l,ix){if((l['for']||OE.order.name)!==p)return;h+='<div style="display:flex;align-items:center;gap:6px;padding:6px 0;border-bottom:1px solid #f0f0f0"><button type="button" data-oe-dec="'+ix+'" style="width:30px;height:30px;border:1px solid #ddd;background:#fff;border-radius:8px;cursor:pointer">−</button><b style="min-width:24px;text-align:center">'+l.q+'</b><button type="button" data-oe-inc="'+ix+'" style="width:30px;height:30px;border:1px solid #ddd;background:#fff;border-radius:8px;cursor:pointer">＋</button><span style="flex:1">'+esc(l.n)+(l.l?' ('+esc(l.l)+')':'')+(l.addons&&l.addons.length?' <span style="color:#888;font-size:12px">＋ '+l.addons.map(function(a){return esc(a.n)}).join('، ')+'</span>':'')+'</span><span>'+n2(l.q*l.p)+' ج</span><button type="button" data-oe-del="'+ix+'" style="border:0;background:none;color:#a92318;font-size:16px;cursor:pointer">✕</button></div>'})});L.innerHTML=h||'<div style="color:#888;padding:8px 0">مفيش أصناف — ضيف صنف من البحث تحت</div>';var t=oeCalc();document.getElementById('oeTot').innerHTML='<div>الأصناف: <b>'+n2(t.sub)+' ج</b></div>'+(t.disc>0?'<div>الخصم: <b>− '+n2(t.disc)+' ج</b></div>':'')+'<div>التوصيل: <b>'+(t.fee?n2(t.fee)+' ج':'مجاني')+'</b></div>'+(t.ptsDisc>0?'<div>خصم النقاط: <b>− '+n2(t.ptsDisc)+' ج</b></div>':'')+'<div>الضريبة: <b>'+n2(t.vat)+' ج</b></div><div style="font-size:17px">الإجمالي الجديد: <b>'+n2(t.total)+' ج</b> <span style="color:#888;font-size:13px">(كان '+n2(OE.order.total)+' ج)</span></div>'+(t.promoDropped?'<div style="color:#a92318">⚠️ البرومو هيتشال — الإجمالي الجديد تحت الحد الأدنى</div>':'')}
function openOrderEdit(id){var o=orders.filter(function(x){return String(x.id)===String(id)})[0];if(!o)return;if(o.status!=='new'){alert('التعديل مسموح بس والأوردر لسه «جديد»');return}OE.order=o;OE.lines=JSON.parse(JSON.stringify(o.items||[]));OE.lines.forEach(function(l){if(!l['for'])l['for']=o.name});document.getElementById('oeTitle').textContent='✏️ تعديل الأصناف — '+o.order_no;document.getElementById('oeMsg').textContent='';document.getElementById('oeMsg').style.color='#a92318';document.getElementById('oeSearch').value='';document.getElementById('oeResults').innerHTML='';getSettings().then(function(st){OE.prices=st.prices||{};OE.cfg=st.config||{};OE.loy=st.loyalty||{};OE.flat=oeBuildFlat();if(o.promo){return api('/rest/v1/rpc/check_promo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p:o.promo,p_phone:o.phone,p_email:null})}).then(function(r){return r.ok?r.json():null}).then(function(j){OE.promo=Array.isArray(j)?j[0]:j;oeRenderLines()})}OE.promo=null;oeRenderLines()}).catch(function(){OE.prices={};OE.flat=oeBuildFlat();OE.promo=null;oeRenderLines()});sheetFit(document.getElementById('oeSheet'));document.getElementById('oeSheet').style.display='flex'}
