function dzDownloadTemplate(br){if(!window.XLSX){msg('dzMsg','مكتبة الإكسل مش محمّلة — اتأكد إن النت شغال وحدّث الصفحة',true);return}var ws=XLSX.utils.aoa_to_sheet([['اسم المنطقة','سعر التوصيل','وقت التوصيل (دقيقة)'],['زهراء المعادي',20,35],['المعادي الجديدة',25,40]]);var wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'مناطق');XLSX.writeFile(wb,'gad-zones-'+br+'.xlsx')}
