function normPhoneAdm(p){p=String(p||'').replace(/[^0-9]/g,'');if(p.indexOf('0020')===0)p=p.slice(2);if(p.indexOf('20')===0&&p.length===12)p='0'+p.slice(2);return p}
var pmXlPhones=[];
function pmParsePhonesFile(f,cb){if(!window.XLSX){cb({err:'مكتبة الإكسل مش محمّلة — اتأكد إن النت شغال وحدّث الصفحة'});return}f.arrayBuffer().then(function(buf){var wb=XLSX.read(buf);var ws=wb.Sheets[wb.SheetNames[0]];var rows=XLSX.utils.sheet_to_json(ws,{header:1});var phones=[],seen={},dups=0,invalid=0;rows.forEach(function(r){var v=r&&r[0];if(v===undefined||v===null||String(v).trim()==='')return;var ph=normPhoneAdm(v);if(!/^01[0125][0-9]{8}$/.test(ph)){invalid++;return}if(seen[ph]){dups++;return}seen[ph]=1;phones.push(ph)});cb({phones:phones,dups:dups,invalid:invalid})}).catch(function(){cb({err:'تعذر قراءة الملف — اتأكد إنه ملف إكسل صحيح'})})}
function pmCrossListWarn(phones,skipCode,cb){api('/rest/v1/promos?select=code,target_customers').then(function(r){return r.ok?r.json():[]}).then(function(rows){var hits={};phones.forEach(function(ph){rows.forEach(function(pr){if(skipCode&&pr.code===skipCode)return;if((pr.target_customers||[]).indexOf(ph)>-1){hits[pr.code]=(hits[pr.code]||0)+1}})});cb(hits)}).catch(function(){cb({})})}
function pmPromoTargets(){var m={},out=[];Array.prototype.slice.call(document.querySelectorAll('#pmPick input:checked')).forEach(function(c){var v=normPhoneAdm(c.value);if(!m[v]){m[v]=1;out.push(v)}});pmXlPhones.forEach(function(v){if(!m[v]){m[v]=1;out.push(v)}});return out}
$('pm_xl').onchange=function(){var f=this.files&&this.files[0];var mm=$('pm_xl_msg');if(!f)return;if(mm)mm.textContent='جاري قراءة الملف…';pmParsePhonesFile(f,function(res){if(res.err){if(mm)mm.textContent='⚠️ '+res.err;return}pmXlPhones=res.phones;pmCrossListWarn(res.phones,null,function(hits){var parts=['✓ تم استقبال '+res.phones.length+' رقم'];if(res.dups)parts.push(res.dups+' مكرر داخل الملف اتشال');if(res.invalid)parts.push(res.invalid+' رقم مش صحيح اتجاهل');Object.keys(hits).forEach(function(c){parts.push(hits[c]+' رقم موجود في كود «'+c+'»')});if(mm)mm.textContent=parts.join(' — ')})})};
