function pmReport(code){var pr=pmRows[code];if(!pr){msg('pmmsg','الكود مش موجود',true);return}if(!window.XLSX){msg('pmmsg','مكتبة الإكسل مش محمّلة — اتأكد إن النت شغال وحدّث الصفحة',true);return}msg('pmmsg','جاري تجهيز التقرير…');api('/rest/v1/orders?select=phone,name,promo,total,created_at,order_no,status&promo=eq.'+encodeURIComponent(code)+'&order=created_at.desc&limit=1000').then(function(r){return r.ok?r.json():[]}).then(function(ords){var list=(pr.target_customers||[]).map(function(v){return normPhoneAdm(v)});var byPhone={};ords.forEach(function(o){if(o.status==='cancelled')return;var ph=normPhoneAdm(o.phone||'');if(!ph)return;var e=byPhone[ph]||(byPhone[ph]={phone:ph,name:o.name||'',uses:0,orders:[],last:''});e.uses++;e.orders.push(o.order_no);if(o.name)e.name=o.name;if(!e.last||o.created_at>e.last)e.last=o.created_at});var maxU=pr.max_uses||null;var used=[],left=[];list.forEach(function(ph){var e=byPhone[ph];var uses=e?e.uses:0;var rem=maxU===null?'∞':Math.max(0,maxU-uses);if(uses>0)used.push({'الرقم':ph,'الاسم':(e&&e.name)||'—','مرات الاستخدام':uses,'المتبقي':rem,'أرقام الأوردرات':(e?e.orders.join('، '):''),'آخر استخدام':(e&&e.last?new Date(e.last).toLocaleString('ar-EG'):'')});if(rem!==0)left.push({'الرقم':ph,'الاسم':(e&&e.name)||'—','استخدم':uses,'المتبقي':rem})});var wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(used.length?used:[{'الرقم':'—','الاسم':'مفيش حد استخدم الكود لسه','مرات الاستخدام':0,'المتبقي':'','أرقام الأوردرات':'','آخر استخدام':''}]),'استخدموا');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(left.length?left:[{'الرقم':'—','الاسم':'مفيش أرقام متبقية','استخدم':0,'المتبقي':0}]),'المتبقي');XLSX.writeFile(wb,'gad-promo-'+code+'-report.xlsx');msg('pmmsg','✓ كود '+code+': استخدمه '+used.length+' رقم من '+list.length+' — التقرير اتنزّل')}).catch(function(){msg('pmmsg','تعذر تجهيز التقرير',true)})}
