function repItemsRows(f){var by={};f.forEach(function(o){if(o.status==='cancelled')return;(o.items||[]).forEach(function(i){var k=i.n+(i.l?' ('+i.l+')':'');if(!by[k])by[k]={n:i.n,l:i.l||'',q:0,rev:0};by[k].q+=Number(i.q||0);by[k].rev+=Number(i.q||0)*Number(i.p||0)})});
 return Object.keys(by).map(function(k){return {'الصنف':by[k].n,'النوع':by[k].l,'الكمية':by[k].q,'الإيراد (ج)':by[k].rev}}).sort(function(a,b){return b['الكمية']-a['الكمية']})}
function repBranchRows(f){var by={};f.forEach(function(o){var b=o.branch||'بدون فرع';if(!by[b])by[b]={b:b,n:0,cx:0,tot:0};by[b].n++;if(o.status==='cancelled'){by[b].cx++;return}by[b].tot+=Number(o.total||0)});
 return Object.keys(by).sort().map(function(b){var x=by[b];return {'الفرع':b,'عدد الطلبات':x.n,'ملغي':x.cx,'الإجمالي (ج)':x.tot,'متوسط الطلب (ج)':x.n-x.cx>0?Math.round(x.tot/(x.n-x.cx)*100)/100:0}})}
function repPointsRows(f){var by={};f.forEach(function(o){var p=o.phone||'—';if(!by[p])by[p]={p:p,nm:o.name||'',n:0,earn:0,red:0};by[p].n++;by[p].earn+=Number(o.points_earned||0);by[p].red+=Number(o.points_redeemed||0);if(o.name)by[p].nm=o.name});
 return Object.keys(by).map(function(p){var x=by[p];return {'الموبايل':p,'الاسم':x.nm,'عدد الطلبات':x.n,'نقاط مكتسبة':x.earn,'نقاط مستبدلة':x.red,'صافي النقاط':x.earn-x.red}}).sort(function(a,b){return b['نقاط مكتسبة']-a['نقاط مكتسبة']})}
function repFileName(base){var d1=$('rd1').value||'all',d2=$('rd2').value||'';return 'gad-'+base+'-'+d1+(d2&&d2!==d1?'_to_'+d2:'')+'.xlsx'}
function repDownload(name,rows,sheet){if(!window.XLSX){msg('rpmsg','مكتبة الإكسل مش محمّلة — اتأكد إن النت شغال وحدّث الصفحة',true);return}
 var wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),sheet||'تقرير');
 XLSX.writeFile(wb,name);msg('rpmsg','✓ تم تنزيل '+name)}
function repAll(){var f=repFiltered();if(!window.XLSX){msg('rpmsg','مكتبة الإكسل مش محمّلة — اتأكد إن النت شغال وحدّث الصفحة',true);return}
 var wb=XLSX.utils.book_new();
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(repOrdersRows(f)),'الطلبات');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(repDailyRows(f)),'المبيعات اليومية');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(repItemsRows(f)),'الأصناف');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(repBranchRows(f)),'الفروع');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(repPointsRows(f)),'النقاط');
 XLSX.writeFile(wb,repFileName('all-reports'));msg('rpmsg','✓ تم تنزيل ملف كل التقارير')}
['rd1','rd2','rb','rs'].forEach(function(i){$(i).addEventListener('change',repSummary)});
$('rp_orders').onclick=function(){repDownload(repFileName('orders'),repOrdersRows(repFiltered()),'الطلبات')};
$('rp_daily').onclick=function(){repDownload(repFileName('daily-sales'),repDailyRows(repFiltered()),'المبيعات اليومية')};
$('rp_items').onclick=function(){repDownload(repFileName('top-items'),repItemsRows(repFiltered()),'الأصناف')};
$('rp_branch').onclick=function(){repDownload(repFileName('branches'),repBranchRows(repFiltered()),'الفروع')};
$('rp_points').onclick=function(){repDownload(repFileName('loyalty'),repPointsRows(repFiltered()),'النقاط')};
$('rp_all').onclick=repAll;
$('bkpBtn').onclick=function(){msg('bkpMsg','جاري تجهيز النسخة…');api('/rest/v1/rpc/export_backup',{method:'POST'}).then(function(r){return r.ok?r.json():null}).then(function(d){if(!d){msg('bkpMsg','تعذّر تجهيز النسخة — جرّب تاني',true);return}var x=Array.isArray(d)?d[0]:d;var blob=new Blob([JSON.stringify(x,null,2)],{type:'application/json'});var aEl=document.createElement('a');aEl.href=URL.createObjectURL(blob);aEl.download='gad-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(aEl);aEl.click();aEl.remove();var n=function(k){return (x[k]&&x[k].length)||0};msg('bkpMsg','✓ تم تنزيل النسخة: '+n('orders')+' أوردر، '+n('profiles')+' ملف شخصي، '+n('promos')+' برومو، '+n('order_messages')+' رسالة شات')}).catch(function(){msg('bkpMsg','تعذّر تجهيز النسخة — جرّب تاني',true)})};
$('blAdd').onclick=function(){var ph=$('bl_phone').value.trim(),em=$('bl_email').value.trim(),rs=$('bl_reason').value.trim()||'أوردر فيك / شكاوى متكررة';if(!ph&&!em){msg('blMsg','اكتب التليفون أو الإيميل',true);return}api('/rest/v1/blacklist',{method:'POST',headers:{'Content-Type':'application/json','Prefer':'return=minimal'},body:JSON.stringify({phone:ph||null,email:em||null,reason:rs,created_by:ROLE})}).then(function(r){if(r.ok){msg('blMsg','✓ اتحظر');$('bl_phone').value='';$('bl_email').value='';$('bl_reason').value='';openBlocklist()}else msg('blMsg','تعذّر الحظر (كود '+r.status+')',true)}).catch(function(){msg('blMsg','تعذّر الحظر',true)})};
$('blList').addEventListener('click',function(e){var b=e.target.closest('button');if(!b||!b.dataset.unbl)return;var unId=b.dataset.unbl;confirmDlg('رفع الحظر','ترفع الحظر عن «'+unId+'»؟',function(){api('/rest/v1/blacklist?id=eq.'+unId,{method:'DELETE',headers:{'Prefer':'return=minimal'}}).then(function(r){if(r.ok){msg('blMsg','✓ اترفع الحظر');openBlocklist()}else msg('blMsg','تعذّر رفع الحظر',true)})},'رفع الحظر')});

